const url = "file:///tmp/issue159-fix-20260925/final-real/candidate/workspace/app/orders.mjs";
import(url).then(({ enrichOrders }) => {
  const mk = (n) => ({ products: Array.from({length:n},(_,i)=>({id:i,name:"p"+i})), orders: Array.from({length:n},(_,i)=>({id:i,productId:i%n})) });
  const timeIt = (fn, o, p) => { const t0=process.hrtime.bigint(); fn(o,p); return Number(process.hrtime.bigint()-t0)/1e6; };
  // warmup
  for (let i=0;i<20;i++){ const d=mk(200); enrichOrders(d.orders,d.products); }
  const mapBased = (orders, products) => { const m=new Map(products.map(p=>[p.id,p])); return orders.map(o=>({...o, product:m.get(o.productId)})); };
  console.log("n\tcurrent_ms(best of 5)\tmapBased_ms\tratio");
  for (const n of [1000,2000,4000,8000,16000,32000]) {
    const d = mk(n);
