    for (let k=0;k<5;k++){ a=Math.min(a,timeIt(enrichOrders,d.orders,d.products)); b=Math.min(b,timeIt(mapBased,d.orders,d.products)); }
    console.log(`${n}\t${a.toFixed(2)}\t${b.toFixed(2)}\t${(a/b).toFixed(1)}x`);
  }
  console.log("complexity ratio check (time doubling when n doubles):");
  let prev=null;
